/**
 * Typed wrapper around the wasm-pack output.
 *
 * `src/wasm/` is generated by `npm run wasm` (gitignored), so the interface is
 * hand-written here instead of importing the generated types.
 */
import init, { lngi_state, parse, start_ms } from '../wasm/btbm_core.js';

export interface LngiState {
    ordinal: string;
    nextOrdinal: string;
    percent: number;
}

/** Display modes (mirroring the branches of `render` on the Rust side). */
export type DisplayMode = 'index' | 'latex' | 'layer' | 'annotated';

/**
 * `html: true` means the mode's output is an HTML fragment (needs `v-html`).
 * Everything except `latex` renders HTML, so the superscript in `(0)(1^(2))`
 * is a real superscript.
 */
export const DISPLAY_MODES: { id: DisplayMode; label: string; html: boolean }[] = [
    { id: 'layer', label: 'layer', html: true },
    { id: 'index', label: 'Index', html: true },
    { id: 'annotated', label: 'annotated', html: true },
    { id: 'latex', label: 'latex', html: false },
];

const HTML_MODES = new Set<DisplayMode>(
    DISPLAY_MODES.filter((m) => m.html).map((m) => m.id),
);

/** Whether the mode's output is HTML. */
export function isHtmlMode(mode: DisplayMode): boolean {
    return HTML_MODES.has(mode);
}

export let START_MS = 0;

/** Load the wasm module (called once at app startup). */
export async function initWasm(): Promise<void> {
    await init();
    START_MS = start_ms();
}

/** The LNGI state at `elapsedMs`. */
export function lngiState(elapsedMs: number, mode: DisplayMode): LngiState {
    return lngi_state(elapsedMs, mode) as LngiState;
}

/** Parse a display string and re-render it in `mode`; throws on failure. */
export function normalize(input: string, mode: DisplayMode): string {
    return parse(input, mode);
}
